<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Dashboard extends MY_Controller {
 public function index(){ $user=$this->require_login();$this->view('customer/dashboard',array('title'=>'Account overview','accounts'=>$this->Account_model->for_user($user['id']),'balance'=>$this->Account_model->total_balance($user['id']),'transactions'=>$this->Account_model->recent_transactions($user['id'])),'customer'); }
 public function transfers(){ $user=$this->require_login(); $data=array('title'=>'Send money','accounts'=>$this->Account_model->for_user($user['id'])); if($this->input->method()==='post'){ $account_id=(int)$this->input->post('account_id'); $amount=(float)$this->input->post('amount'); $account=$this->db->get_where('accounts',array('id'=>$account_id,'user_id'=>$user['id'],'status'=>'active'))->row_array(); if(!$account || $amount<=0 || $amount>$account['balance']){$this->session->set_flashdata('notice','Please enter an amount within your available balance.');redirect('transfers');} $this->db->insert('transactions',array('account_id'=>$account_id,'type'=>'transfer','amount'=>$amount,'direction'=>'debit','description'=>'Transfer to '.$this->input->post('recipient',TRUE),'reference'=>'TRF'.strtoupper(random_string('alnum',12)),'status'=>'pending','created_at'=>date('Y-m-d H:i:s'))); $this->session->set_flashdata('notice','Transfer request received and is pending review.');redirect('transfers');}$this->view('customer/transfers',$data,'customer');}
 public function cards(){ $user=$this->require_login();$this->view('customer/cards',array('title'=>'My cards','cards'=>$this->db->get_where('cards',array('user_id'=>$user['id']))->result_array()),'customer');}
 public function kyc(){ $user=$this->require_login(); if($this->input->method()==='post'){$this->db->insert('kyc_applications',array('user_id'=>$user['id'],'document_type'=>$this->input->post('document_type',TRUE),'document_number'=>$this->input->post('document_number',TRUE),'status'=>'pending','created_at'=>date('Y-m-d H:i:s')));$this->session->set_flashdata('notice','Your identity verification was submitted.');redirect('kyc');}$this->view('customer/kyc',array('title'=>'Verify identity'),'customer');} public function loans(){ $user=$this->require_login();if($this->input->method()==='post'){$this->db->insert('loans',array('user_id'=>$user['id'],'amount'=>$this->input->post('amount'),'purpose'=>$this->input->post('purpose',TRUE),'term_months'=>$this->input->post('term_months'),'status'=>'pending','created_at'=>date('Y-m-d H:i:s')));$this->session->set_flashdata('notice','Your loan request was submitted.');redirect('loans');}$this->view('customer/loans',array('title'=>'Request a loan'),'customer');} public function request_card(){ $user=$this->require_login(); if($this->input->method()!=='post')redirect('cards');$this->db->insert('cards',array('user_id'=>$user['id'],'card_type'=>$this->input->post('card_type')==='physical'?'physical':'virtual','status'=>'pending','created_at'=>date('Y-m-d H:i:s')));$this->session->set_flashdata('notice','Your card application has been submitted.');redirect('cards');} public function profile(){ $this->require_login();$this->view('customer/profile',array('title'=>'My profile'),'customer');}
}
